render-mode.text:
[
{"t": "text", "id": "GalleryTaskIntro", "text": "A .qvue screen with a tui twin: the form posts to the same saveTask transition."},
${JSON.stringify((() => {
    const parameters = (ec.web && ec.web.parameters) || {}
    const entityName = recordEntity || parameters.recordEntity || ''
    const entityId = recordId || parameters.recordId || ''
    const nodes = []
    if (entityId) nodes.push({t: 'text', id: 'GalleryTaskRecord', text: 'On ' + entityName + ' ' + entityId})
    nodes.push({t: 'form', id: 'GalleryTask', name: 'GalleryTask', transitionUrl: sri.buildUrl('saveTask').url, method: 'post',
        hidden: [{name: 'recordEntity', value: String(entityName)}, {name: 'recordId', value: String(entityId)}],
        c: [{t: 'field', id: 'GalleryTask_taskName', name: 'taskName', title: 'Task', w: {kind: 'textLine', value: ''}},
            {t: 'field', id: 'GalleryTask_submit', name: 'submitButton', title: 'Save', w: {kind: 'submit', text: 'Save'}}]})
    return {t: 'container', id: 'GalleryTaskBody', c: nodes}
})())}
]
